from lib import *
S = SS('g99')
steps = [
    step("一个故意写了各种问题的文件,go vet 报告了 16 条(退出码 1)。lostcancel:the cancel function is not used on all paths (possible context leak),以及 this return statement may be reached without using the cancel var;unusedresult:result of fmt.Sprintf call not used;waitgroup:WaitGroup.Add called from inside new goroutine;bools:redundant or: a == 1 || a == 1;errorsas:second argument to errors.As must be a non-nil pointer …;httpresponse:using resp before checking for errors;printf 三条:%d 配了字符串、Println 参数以多余的换行结尾、%s 读第 2 个参数但只给了 1 个;shift:x (32 bits) too small for shift of 40;stringintconv:conversion from int to string yields a string of one rune, not a string of digits;structtag:struct field tag `json: \"b\"` … bad syntax for struct tag value;unreachable:unreachable code;assign:self-assignment of x;copylocks:CopyLock passes lock by value: lab.T contains sync.Mutex。(写了 `json:\"a\" json:\"b\"` 的重复 key,这一条没有被报告。)", t=tl(S(1)), done=lidx(S(1), 'cancel function', 'Sprintf call not used', 'WaitGroup.Add called', 'redundant or', 'errors.As', 'using resp before', 'passes lock by value'), mark=lidx(S(1), 'fmt.Printf format %d', 'redundant newline', 'reads arg #2', 'too small for shift', 'conversion from int to string', 'struct field tag', 'unreachable code', 'self-assignment'), b=bars([['触发的检查器个数', 13, '13 个'], ['vet 报告条数', 16, '16 条']], 16, done=[1], mark=[0]), kv=KV([['报告数', '16 条(来自 13 个检查器;lostcancel 报 2 条、printf 报 3 条)'], ['没报的', '重复的 json tag key'], ['先决条件', '代码必须能通过编译,否则只报编译错误']], ['先决条件'])),
    step("vet 里有多少个检查器(go tool vet help):共 35 个——appends asmdecl assign atomic bools buildtag cgocall composites copylocks defers directive errorsas framepointer hostport httpresponse ifaceassert loopclosure lostcancel nilfunc printf shift sigchanyzer slog stdmethods stdversion stringintconv structtag testinggoroutine tests timeformat unmarshal unreachable unsafeptr unusedresult waitgroup。", t=tl(S(2)), mark=lidx(S(2), '共 35 个'), kv=KV([['检查器个数', '35'], ['本文触发了', '13 个']], ['检查器个数'])),
    step("go test 自带的 vet 只跑一小部分:代码里同时有 printf 问题和 copylocks 问题时,go test 退出码 1,FAIL lab [build failed],只报告 printf 一条(./v.go:15:29 …wrong type string);只有 copylocks 问题时,go test 退出码 0,ok(0.102s)——测试通过了;同样的代码 go vet 退出码 1,报 CopyLock passes lock by value。", t=tl(S(3)), mark=lidx(S(3), '退出码 1;FAIL', '同样的代码 go vet'), done=lidx(S(3), '只有 copylocks 问题时 go test'), kv=KV([['go test 的 vet', 'printf 等一小撮高置信度检查'], ['copylocks', 'go test 不查,只有 go vet 才查'], ['含义', 'CI 里要单独跑 go vet']], ['含义'])),
    step("go help test:作为构建测试二进制的一部分,go test 会对包及其测试源文件运行 go vet;如果 vet 发现问题,go test 报告它们且不运行测试二进制;只使用默认 vet 检查中高置信度的子集:atomic、bools、buildtag、directive、errorsas、ifaceassert、nilfunc、printf、stdversion、stringintconv 和 tests;用 -vet=off 可以关闭。", t=tl(S(4)), done=lidx(S(4), 'As part of building a test binary'), kv=KV([['go test 中的 vet 子集', '11 个检查器'], ['关闭', '-vet=off'], ['发现问题时', '不运行测试二进制']], ['go test 中的 vet 子集'])),
]
A = mkartg('g99', 99, 'Go,go vet,静态检查,printf,copylocks,lostcancel,真实验证,动画演示',
    '在 Go 1.27.1 里实测 go vet:一个故意写了十几类问题的文件被报告了 16 条(来自 13 个检查器)(printf、copylocks、lostcancel、shift、stringintconv、httpresponse、waitgroup、unreachable 等);vet 共有 35 个检查器;go test 自带的 vet 只跑 11 个高置信度的检查,所以 copylocks 问题能通过 go test 却会被 go vet 拦下。',
    'go vet 能抓到编译器放过的一类错误:格式串和参数不匹配、拷贝了锁、忘了调用 cancel。这篇写一个包含十几种典型错误的文件,看 vet 逐条报了什么,漏了什么,并验证 go test 里自带的那份 vet 只是它的一小部分。',
    [('16 条', '一个故意写错的文件,go vet 的报告数'), ('35 个', 'go tool vet help 列出的检查器个数'), ('11 个', 'go test 自带的 vet 所跑的检查器个数,copylocks 不在其中')],
    [('典型错误一次看完', '<p>格式串与参数不符、<code>Println</code> 末尾多一个换行、拷贝含 <code>Mutex</code> 的结构体、<code>cancel</code> 没在所有路径上调用、<code>WaitGroup.Add</code> 写在 goroutine 里面、<code>string(int)</code>、位移超过类型宽度、<code>errors.As</code> 第二个参数不是指针、在检查 err 之前就用 <code>resp</code>……都被 vet 指出了位置和原因。重复的 <code>json</code> tag key 没有被报告,所以 vet 不是完备的。</p>'),
     ('先决条件', '<p>vet 要代码能通过类型检查。我第一次写的文件里有“声明了 cancel 没使用”和“缺少 return”两个编译错误,vet 只报了这一条编译错误就停了,后面的检查一条都没跑。</p>'),
     ('go test 里的 vet', '<p>go test 会先跑一个高置信度子集(11 个检查器),发现问题就不运行测试。实验里同时有 printf 和 copylocks 问题时,go test 以 printf 问题失败;只有 copylocks 问题时,go test 通过,go vet 却失败。所以持续集成里要单独跑 <code>go vet ./...</code>。</p>'),
     ('文档', '<p>go help test 列出的子集是 atomic、bools、buildtag、directive、errorsas、ifaceassert、nilfunc、printf、stdversion、stringintconv、tests,<code>-vet=off</code> 可关闭。</p>')],
    steps,
    [ENV_G + '。被检查的文件是自己写的,每个检查器至少写了一个典型错误;报告条数按 go vet ./... 的输出行数;检查器清单来自 go tool vet help;读过的文档:go help test 中关于 vet 的一段',
     '没有验证:每个检查器的准确率与误报、自定义 vet 工具(-vettool)、go vet -json 输出、结构体 tag 重复 key 为什么没有被报、loopclosure 在新语言版本下基本不再触发的情况、与 staticcheck 等第三方检查器的差别'],
    'go vet')
